# Generated by build.py from recipe.yml for recipe ftp-offer-a-share-to-ftp-only. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'drop', 'public' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'drop/report.txt'), "totals`n")
[IO.File]::WriteAllText((Join-Path $PWD 'public/readme.txt'), "open to all`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--list-directories', '--self-signed', '--share', '"drop=drop;protocols=ftp"', '--share', 'public=public', 'ftp://127.0.0.1:8080/', 'http://127.0.0.1:8081/', 'ftps://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s ftp://127.0.0.1:8080/drop/report.txt } finally { Stop-Process $server0 }
